import unittest
from TreeSpotterFoldingFunction2 import FoldingFunction2
from SubFunctions.PhyloGeneticNetwork import PhylogeneticNetwork
from SubFunctions.BiPartiteGraph import BiPartiteGraph
from SubFunctions.MultiLabelledGraph import MultiLabelledGraph

class UnitTests(unittest.TestCase):
    def test_import(self):
        preset1_vertices = []
        for i in range(0, 12):
            preset1_vertices.append(i)
        preset1_arcs = [[0, 1], [1, 2], [1, 3], [2, 5], [2, 6], [3, 4], [3, 5], [4, 6], [4, 7], [5, 8], [6, 9], [7, 8],
                        [7, 9], [8, 10], [9, 11]]
        temp_phylo_network = PhylogeneticNetwork(preset1_vertices, preset1_arcs, 0)
        tff2 = FoldingFunction2(temp_phylo_network)
        self.assertEqual(tff2.network, temp_phylo_network, 'Network did not import correctly into FoldingFunction2')

    def test_forbidden_configuration_1(self):
        preset2_vertices = [0]
        for i in range(1, 8):
            preset2_vertices.append(i)
        preset2_arcs = [[0, 1], [1, 2], [1, 3], [2, 4], [2, 5], [3, 4], [3, 5], [4, 6], [5, 7]]
        temp_phylo_network = PhylogeneticNetwork(preset2_vertices, preset2_arcs, 0)
        tff2 = FoldingFunction2(temp_phylo_network)
        temp_bipartite_graph = temp_phylo_network.makeBiPartiteGraph()
        self.assertEqual(tff2.checkForForbiddenConfiguration1(temp_phylo_network, temp_bipartite_graph), (True, [[3, 0]], [[4, 5]], [[[3, 4], [3, 5], [0, 4], [0, 5]]]), 'Check for forbidden configuration 1 broken')

    def test_forbidden_configuration_2(self):
        preset3_vertices = [0]
        for i in range(1, 7):
            preset3_vertices.append(i)
        preset3_arcs = [[0, 1], [1, 2], [1, 3], [2, 4], [2, 5], [3, 4], [3, 5], [4, 6], [5, 6]]
        temp_phylo_network = PhylogeneticNetwork(preset3_vertices, preset3_arcs, 0)
        N = temp_phylo_network
        tff2 = FoldingFunction2(N)
        GN = N.makeBiPartiteGraph()
        # GN.displayGraph()
        fn_exists, fn_tree_vertices, fn_reticulation_vertices, fn_edges = tff2.checkForForbiddenConfiguration1(N, GN)
        check = False
        if fn_exists:
            for i in range(len(fn_tree_vertices)):
                if tff2.checkForbiddenConfiguration2(fn_tree_vertices[i], fn_reticulation_vertices[i], N):
                    check = True
        self.assertEqual(check, True, 'Check for Forbidden Configuration 2 failed')

    def test_foldNetworkSimplifiedMLG(self):
        preset1_vertices = []
        for i in range(0, 12):
            preset1_vertices.append(i)
        preset1_arcs = [[0, 1], [1, 2], [1, 3], [2, 5], [2, 6], [3, 4], [3, 5], [4, 6], [4, 7], [5, 8], [6, 9], [7, 8],
                        [7, 9], [8, 10], [9, 11]]
        temp_phylo_network = PhylogeneticNetwork(preset1_vertices, preset1_arcs, 0)
        tff2 = FoldingFunction2(temp_phylo_network)
        MN = MultiLabelledGraph(temp_phylo_network)
        NPrime = tff2.foldNetworkSimplifiedMLG(MN)
        # NPrime.displayGraph()
        ## print("NPRIME.VERTICES")
        ## print(NPrime.vertices)
        ## print("NPRIME.ARCS")
        ## print(NPrime.arcs)
        self.assertEqual(NPrime.vertices, [0, 1, 2, 10, 3, 4, 11, 23, 24, 25], 'Fold Network Simplified MLG broken')
